contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address callee, bytes memory data) public {
        // If callee itself is the test contract, define receive to always revert,
        // so that forwarding empty data to it is a guaranteed inner-call failure.
        bool innerReverted;
        try InvMutTest(address(callee)).revertOnReceive() {
            innerReverted = false;
        } catch {
            innerReverted = true;
        }

        bool outerReverted;
        try c.forward(callee, data) {
            outerReverted = false;
        } catch {
            outerReverted = true;
        }

        assert(!(innerReverted && !outerReverted));
    }

    function revertOnReceive() external pure {
        revert();
    }

    receive() external payable {
        revert();
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address callee) public {
        // Since we cannot force an arbitrary external call to always revert,
        // we use a call to the zero address with non-empty calldata,
        // which is guaranteed to fail (calls to an EOA with data revert).
        bytes memory data = hex"00";

        bool outerReverted;
        try c.forward(callee, data) {
            outerReverted = false;
        } catch {
            outerReverted = true;
        }

        // General rule: if the target is the zero address (always reverts for non-empty data),
        // then forward must revert.
        assert(callee != address(0) || outerReverted);
    }
}

